  return `<div class="card" style="margin-bottom:16px"><div class="row wrap" style="gap:8px"><select class="input" style="width:auto" data-change="sc-upcol" aria-label="Collection"><option value="">Choose a collection…</option>${(cols || []).map(c => `<option value="${c.id}" ${SC.upCol === c.id ? 'selected' : ''}>${esc(c.name)}</option>`).join('')}</select><button class="btn ghost" data-act="sc-newcol">${icon('add')}New collection</button><span class="grow"></span><span class="small muted">Bulk:</span><button class="btn ghost" data-act="sc-bulk-up" data-v="zip">Upload a .zip</button><button class="btn ghost" data-act="sc-bulk-up" data-v="sheet" data-tip="An .xlsx or .csv of Google Drive links. The server fetches each file">Upload a link sheet</button></div>
      <button class="empty" style="width:100%;margin-top:12px" data-act="sc-upload">${icon('upload_file')}Drop résumés here, or browse<br><span class="small faint">25 MB each · PDF, Word or text</span></button></div>
    <div class="row" style="margin-bottom:10px"><div class="seg"><button class="${SC.scope === 'mine' ? 'on' : ''}" data-act="sc-scope" data-v="mine">Mine</button><button class="${SC.scope === 'all' ? 'on' : ''}" data-act="sc-scope" data-v="all">Everyone</button></div></div>
    ${!U ? loading : !U.length ? `<div class="empty">${icon('inbox')}Nothing uploaded yet.</div>` : `<div class="card"><table class="list"><tr><th>File</th><th>Stage</th><th>Size</th><th>Uploaded</th><th>Actions</th></tr>${U.map(x => `<tr><td><b>${esc(x.file)}</b><div class="small muted">${esc(x.collection)}${SC.scope === 'all' ? ' · ' + esc(x.by) : ''}</div></td><td>${chip(x.stage, st[x.stage] || 'warn')}${x.attempts > 1 ? `<div class="small faint">Processing attempts so far: ${x.attempts}</div>` : ''}</td><td>${size(x.size)}</td><td class="small muted">${ago(x.at)}</td><td class="act">${x.stage === 'Searchable' ? `<button class="icon-btn sm" data-act="sc-insearch" data-name="${esc(x.file.replace(/\.\w+$/, '').replace(/_/g, ' '))}" data-tip="Open in search" aria-label="Open in search">${icon('search')}</button>` : ''}<button class="icon-btn sm" data-act="sc-retry" data-id="${x.id}" data-tip="Process it again" aria-label="Process it again">${icon('refresh')}</button><button class="icon-btn sm" data-act="sc-del" data-id="${x.id}" data-tip="Delete this upload and its file" aria-label="Delete">${icon('delete')}</button></td></tr>`).join('')}</table></div>`}`;
