const MB = { mode: 'single', files: [], disc: 'auto', room: '', dim: '', vl: false, tool: '', pts: [], hide: false, group: false, side: true, view: '2d', sel: '', zoom: 100, scaleOn: false, scalePts: [], edit: false, model: null, btab: 'all', busy: false };
