acts['mb-start'] = async () => { if (!MB.files.length) return toast(MB.mode === 'batch' ? 'Drop at least one PDF drawing.' : 'Drop a PDF drawing first.', 'err'); MB.busy = true; rerender(); const o = { discipline: MB.disc, scaleRoom: MB.room, scaleDim: MB.dim, vlVerify: MB.vl }; try { if (MB.mode === 'batch') { const r = await api('POST', '/api/measurebook/analyze-batch', { ...o, files: MB.files }); MB.files = []; go('#/app/measurebook/batch/' + r.batch_job_id); } else { const r = await api('POST', '/api/measurebook/analyze', { ...o, file: MB.files[0] }); MB.files = []; mbReset(); go('#/app/measurebook/job/' + r.job_id); } } catch (e) { toast(e.message, 'err'); } MB.busy = false; rerender(); };
acts['mb-tool'] = el => { menu(el, [['count', 'Point count'], ['line', 'Line length (RMT)'], ['area', 'Area (SQMT)'], ['', 'Off']].map(t => ({ label: t[1], run: () => { MB.tool = t[0]; MB.pts = []; MB.scaleOn = false; rerender(); } }))); };
acts['mb-scale'] = () => { MB.scaleOn = !MB.scaleOn; MB.scalePts = []; MB.tool = ''; rerender(); };
acts['mb-apply-scale'] = async () => { const mm = +($('#mb-mm') || {}).value; if (MB.scalePts.length < 2 || !(mm > 0)) return toast('Need two clicked points and a distance value', 'err'); const j = await put('mbJob', 'PUT', `/api/measurebook/jobs/${P.mbJob.id}/scale`, { sheet: 1, a: MB.scalePts[0], b: MB.scalePts[1], mm }); if (j) { MB.scaleOn = false; MB.scalePts = []; rerender(); } };
acts['mb-click'] = (el, e) => { if (!MB.tool && !MB.scaleOn) return; const svg = el.closest('svg'), r = svg.getBoundingClientRect(), pt = [Math.round((e.clientX - r.left) * 800 / r.width), Math.round((e.clientY - r.top) * 520 / r.height)]; if (MB.scaleOn) MB.scalePts = [...MB.scalePts, pt].slice(-2); else MB.pts = [...MB.pts, pt]; rerender(); };
acts['mb-undo'] = () => { MB.pts = []; rerender(); };
acts['mb-flag'] = el => { MB[el.dataset.k] = !MB[el.dataset.k]; rerender(); };
acts['mb-view'] = el => { MB.view = el.dataset.v; rerender(); };
