  const base = s.line ? `<polyline points="${s.line.map(q => q.join(',')).join(' ')}" fill="none" stroke="currentColor" stroke-width="2.5"/><polyline points="230,220 230,290" fill="none" stroke="currentColor" stroke-width="2"/><text x="90" y="330" font-size="11" fill="currentColor">100-CW-101-A1A</text>` : s.rooms.map(r => `<rect x="${r[1]}" y="${r[2]}" width="${r[3]}" height="${r[4]}" fill="none" stroke="currentColor" stroke-width="2"/><text x="${r[1] + r[3] / 2}" y="${r[2] + r[4] / 2 - 4}" text-anchor="middle" font-size="11" fill="currentColor" opacity=".7">${r[0]}</text><text x="${r[1] + r[3] / 2}" y="${r[2] + r[4] / 2 + 10}" text-anchor="middle" font-size="9" fill="currentColor" opacity=".45">${r[5]}</text>`).join('');
