acts['bt-ask'] = async () => { const el = $('#bt-chat'), q = el.value.trim(); if (!q) return; BT.chat.push({ q, a: null }); rerender(); try { BT.chat[BT.chat.length - 1].a = await api('POST', '/api/mbot/chat', { q }); } catch (e) { BT.chat[BT.chat.length - 1].a = { answer: e.message, sources: [] }; } rerender(); };
acts['bt-inc'] = async () => { const s = P.btSet; await api('PUT', '/api/mbot/settings', { includeTranscript: !s.includeTranscript }); fresh('btSet'); rerender(); };
acts['bt-focus-add'] = () => modal({ title: 'Add a focus contact', text: 'Meetings that include this person will be flagged as visible to the CEO office.', body: `<div class="stack" style="gap:10px"><input class="input" id="bf-n" placeholder="Name, e.g. Priya Nair"><input class="input" id="bf-e" placeholder="Email, name@company.com"><input class="input" id="bf-d" placeholder="Designation (optional), e.g. VP Operations"><input class="input" id="bf-c" placeholder="Company (optional), e.g. Partner Co"></div>`, actions: [{ label: 'Add contact', run: async o => { const n = $('#bf-n', o).value; await api('POST', '/api/mbot/focus', { name: n, email: $('#bf-e', o).value, designation: $('#bf-d', o).value, company: $('#bf-c', o).value }); toast(`${n} added to your focus contacts`); fresh('btSet', 'btList', 'btHome'); rerender(); } }] });
acts['bt-focus-del'] = el => confirmBox('Remove focus contact?', `${el.dataset.name} (${el.dataset.email}) will no longer be a focus contact. Meetings with them stop being flagged for the CEO office.`, 'Remove', async () => { await api('DELETE', '/api/mbot/focus/' + el.dataset.id); toast(`${el.dataset.name} removed from your focus contacts`); fresh('btSet', 'btList', 'btHome'); rerender(); }, true);
export function mbotPage(tab = '', id) {
  if (!BTTABS.some(t => t[0] === tab)) tab = '';
  let body;
  if (tab === 'meetings') body = id ? btMeeting(id) : btMeetings();
  else if (tab === 'chat') body = `<div class="card" style="max-width:820px">${BT.chat.length ? BT.chat.map(c => `<div style="margin-bottom:16px"><p><b>${esc(c.q)}</b></p>${!c.a ? loading : `<p style="margin-top:6px">${esc(c.a.answer)}</p>${c.a.sources.map(s => `<a class="tag" style="margin:6px 6px 0 0" href="#/app/mbot/meetings/${s.meetingId}">${esc(s.meeting)} · ${esc(s.who)} ${s.t}</a>`).join('')}`}</div>`).join('') : '<p class="muted">Ask a question across your past meetings. Answers come from their transcripts.</p>'}<div class="row" style="gap:8px;margin-top:10px"><input class="input grow" id="bt-chat" data-enter="bt-ask" placeholder="Search meetings, actions, people…"><button class="btn" data-act="bt-ask">Ask</button></div></div>`;
  else if (tab === 'settings') { const s = get('btSet', 's', '/api/mbot/settings'); body = !s ? loading : `<div class="stack" style="gap:16px;max-width:760px"><div class="card"><div class="set-row"><div class="grow"><div class="lbl">Include Transcript</div><div class="small muted">Turn the meeting transcript on or off</div></div>${sw(s.includeTranscript, 'bt-inc', 'Include Transcript')}</div></div>
      <div class="card"><div class="card-head"><h3>Focus contacts</h3>${info('Meetings with these people are flagged as visible to the CEO office.')}<span class="grow"></span><button class="btn ghost" data-act="bt-focus-add">${icon('add')}Add contact</button></div><p class="small muted">People whose meetings you want highlighted. Add or remove the contacts you've set up.</p>${s.focus.length ? s.focus.map(f => `<div class="set-row"><div class="grow"><div class="lbl">${esc(f.name)}</div><div class="small muted">${esc(f.email)}${f.designation ? ' · ' + esc(f.designation) : ''}${f.company ? ' · ' + esc(f.company) : ''}</div></div><button class="btn ghost" data-act="bt-focus-del" data-id="${f.id}" data-name="${esc(f.name)}" data-email="${esc(f.email)}">Remove</button></div>`).join('') : "<p class=\"muted\" style=\"margin-top:10px\">You haven't added any focus contacts yet.</p>"}</div></div>`; }
  else body = btHome();
  return appShell('mbot', 'mBot', `${tab === 'meetings' && id ? '' : tabs('#/app/mbot', BTTABS, tab)}${body}`);
}

// =====================================================================================================================
// Vanik Echo
// =====================================================================================================================
acts['ec-start'] = async () => { try { const m = await api('POST', '/api/echo/meetings', { title: ($('#ec-title') || { value: '' }).value }); fresh('ecList'); go('#/app/echo/' + m.id); } catch (e) { toast(e.message, 'err'); } };
acts['ec-end'] = async el => { await put('ecMeet', 'POST', `/api/echo/meetings/${el.dataset.id}/end`); fresh('ecList'); toast('Transcript saved on the appliance.'); };
acts['ec-dl'] = () => { const m = P.ecMeet; downloadText(m.title.replace(/[^\wऀ-ॿ ]+/g, '').trim() + '.txt', m.lines.map(l => `[${l.t}] ${l.speaker}: ${l.text}`).join('\n')); };
acts['ec-del'] = el => confirmBox('Delete this transcript?', 'It is removed from the appliance.', 'Delete', async () => { await api('DELETE', '/api/echo/meetings/' + el.dataset.id); fresh('ecList'); go('#/app/echo'); }, true);
let ecTimer = 0;
export function echoPage(id) {
  if (id) {
    const m = get('ecMeet', id, '/api/echo/meetings/' + id); if (!m) return appShell('echo', 'Echo', loading);
    if (m.live && m.more && !ecTimer) ecTimer = setTimeout(async () => { ecTimer = 0; if (!on('#/app/echo/' + id)) return; try { P.ecMeet = await api('POST', `/api/echo/meetings/${id}/utterance`); rerender(); const sc = $('#scroll'); if (sc) sc.scrollTop = sc.scrollHeight; } catch (e) { /* ended elsewhere */ } }, 2400);
    return appShell('echo', `<a href="#/app/echo">Echo</a> / ${esc(m.title)}`, `<a class="back" href="#/app/echo">${icon('arrow_back')}Meetings</a><div class="page-head"><div class="grow"><h1>${esc(m.title)}</h1><p class="sub">${day(m.startedAt)} · ${m.count} utterances · ${m.speakers} speakers · ${m.language}</p></div>${m.live ? `${chip(m.more ? 'Listening' : 'Waiting for speech', 'ok')}<button class="btn" data-act="ec-end" data-id="${m.id}">${icon('stop_circle')}End meeting</button>` : `<button class="btn ghost" data-act="ec-dl">${icon('download')}Download</button><button class="icon-btn" data-act="ec-del" data-id="${m.id}" aria-label="Delete">${icon('delete')}</button>`}</div>
      <div class="card" style="max-width:860px">${m.lines.length ? m.lines.map(l => `<div class="set-row" style="align-items:flex-start;gap:12px"><span class="tag ${['on', '', 'on bad'][(+l.speaker.split(' ')[1] - 1) % 3] || ''}" style="flex:none">${esc(l.speaker)}</span><div class="grow" lang="hi" style="font-size:15px;line-height:1.7">${esc(l.text)}</div><span class="small faint mono">${l.t}</span></div>`).join('') : '<p class="muted">Start talking. Each utterance appears after a pause, labelled with who said it.</p>'}</div>`);
  }
  const L = get('ecList', 'l', '/api/echo'), live = L && L.meetings.find(m => m.live);
  return appShell('echo', 'Echo', `<div class="page-head"><div class="grow"><h1>Echo</h1><p class="sub">Live meeting transcription with speaker labels, on your own Vanik Appliance.</p></div></div>
    <div class="card" style="max-width:760px;margin-bottom:16px">${live ? `<div class="row"><div class="grow"><b>${esc(live.title)}</b><div class="small muted">A meeting is running</div></div><a class="btn" href="#/app/echo/${live.id}">Open</a></div>` : `<div class="row wrap" style="gap:8px"><input class="input grow" id="ec-title" data-enter="ec-start" placeholder="Meeting title (optional)"><button class="btn" data-act="ec-start">${icon('mic')}Start a meeting</button></div><p class="small faint" style="margin-top:10px">Hindi only for now. Audio is segmented on pauses and transcribed utterance by utterance. Transcripts are saved on the device when the meeting ends.</p>`}</div>
    ${!L ? loading : !L.meetings.filter(m => !m.live).length ? `<div class="empty" style="max-width:760px">${icon('graphic_eq')}No transcripts yet.</div>` : `<div class="card" style="max-width:760px"><div class="card-head"><h3>Saved transcripts</h3></div>${L.meetings.filter(m => !m.live).map(m => `<a class="set-row" href="#/app/echo/${m.id}"><div class="grow"><div class="lbl" lang="hi">${esc(m.title)}</div><div class="small muted">${day(m.startedAt)} · ${m.count} utterances · ${m.speakers} speakers</div></div>${icon('chevron_right')}</a>`).join('')}</div>`}`);
}
